-- Datos sintéticos de morosidad


SELECT setval(pg_get_serial_sequence('morosidad', 'id_morosidad'), (SELECT MAX(id_morosidad) FROM morosidad));

-- Estado de los créditos con atraso grave a la fecha de corte
UPDATE credito SET estado_credito = 'COBRO_JUDICIAL' WHERE id_credito IN (65, 145, 439, 518, 519, 555, 574, 680, 720, 922, 948, 1053);
UPDATE credito SET estado_credito = 'CASTIGADO' WHERE id_credito IN (22, 27, 167, 209, 221, 245, 289, 295, 338, 368, 377, 391, 403, 416, 423, 428, 500, 592, 597, 675, 714, 776, 813);
